Deno.test("item-rarity audit sorts, filters, and flags legacy slots deterministically", () => {
  const items = auditItems([
    { id: "zeta", name: "Zeta", catalogKind: "magic", type: "potion", rarity: 2, rarityName: "magic", tags: ["artifact"] },
    { id: "alpha", name: "Alpha", catalogKind: "equipment", type: "equip", slot: "weapon", rarity: 2, rarityName: "uncommon", tags: ["unique"] },
  ]);
  assertEquals(items.map((item) => item.id), ["alpha", "zeta"]);
  assertEquals(filterItems(items, { kind: "equipment", rarity: "", gearOnly: true, issues: false }).length, 1);
  assertEquals(filterItems(items, { kind: "", rarity: "", gearOnly: false, issues: true }).map((item) => item.id), ["zeta"]);
  assert(formatReport(items, "csv").startsWith("id,name,catalogKind,type,slot,rarity,rarityName"));
  assert(formatReport(items, "csv").includes("unique"));
});

Deno.test("item-strength audit is deterministic and explains its score", () => {
  const item = {
    id: "test_blade",
    name: "Test Blade",
    catalogKind: "equipment",
    slot: "weapon",
    rarity: 2,
    rarityName: "uncommon",
    bonuses: { attack: 2 },
    damageDice: "1d8",
    staminaCost: 4,
    maxSockets: 1,
    affixes: ["test_affix"],
    procPackages: ["test_proc"],
  };
  const first = scoreItem(item);
  const second = scoreItem(item);
  assertEquals(first, second);
  assert(first.score > 0);
  assert(first.contributions.some((entry) => entry.label === "weapon:average-damage"));
  const ammo = scoreItem({ ammoAffinities: { arrows: { damageBonus: 1, fireSpreadChanceBonus: 0.15 } } });
  assert(ammo.contributions.some((entry) => entry.label === "ammo-affinities"));
  assertEquals(ammo.manualReview, ["ammo-affinity-context"]);
  const cursed = scoreItem({ bonuses: { defense: -2 }, slot: "ring" });
  assert(cursed.contributions.some((entry) => entry.points < 0));
  assertEquals(cursed.score, 0);
  assertEquals(filterStrengthItems(auditStrength([item]), { slot: "weapon", rarity: "uncommon", outliers: false }).length, 1);
});

